// 2) 게시글의 댓글/좋아요는 BatchSize로 묶어 IN 절 배치 조회
@Entity
public class Board {
    @BatchSize(size = 100)
    @OneToMany(mappedBy = "board")
    private List<Comment> comments;

    @BatchSize(size = 100)
    @OneToMany(mappedBy = "board")
    private List<Likes> likes;
}

// 3) User의 roles/likes는 기본 EAGER라 작성자가 조회될 때마다 함께 로딩됨
//    실제 사용 시점에만 조회되도록 LAZY로 전환
@Entity
public class User {
    @ElementCollection(fetch = FetchType.LAZY)
    private Set<Role> roles;

    @OneToMany(mappedBy = "user", fetch = FetchType.LAZY)
