void rewrite_packet(struct iphdr *ip, struct tcphdr *tcp,
                     uint32_t new_addr, uint16_t new_port) {
    ip->daddr = new_addr;
    tcp->dest = new_port;

    // 헤더 수정 후 체크섬을 반드시 재계산
    ip->check = 0;
    ip->check = checksum((uint16_t *)ip, ip->ihl * 4);
    tcp->check = tcp_checksum(ip, tcp);
}

